CREATE VIEW frinv_New143 AS SELECT H.NUMBER, (   (ISNULL(MAX(DTL.NetTotal), 0) + MAX(H.MABL_HAZ) + MAX(H.MBAA) - MAX(H.TAKHFIF))   -   (MAX(H.M_NAGHD) + MAX(H.MABL_VAR) + MAX(H.MABL_HAV) + ISNULL(MAX(CHK.mabch), 0)) ) AS Expr1 FROM dbo.HEAD_LST H INNER JOIN (     SELECT NUMBER, TAG, SUM(MABL_K) as NetTotal     FROM dbo.INVO_LST     GROUP BY NUMBER, TAG ) DTL ON H.NUMBER = DTL.NUMBER AND H.TAG = DTL.TAG + 11 LEFT OUTER JOIN dbo.jamchkfact CHK ON DTL.NUMBER = CHK.NUMBER WHERE (H.TAG = 13) AND (H.CUST_NO = N'115-26-36') GROUP BY H.NUMBER HAVING (   (ISNULL(MAX(DTL.NetTotal), 0) + MAX(H.MABL_HAZ) + MAX(H.MBAA) - MAX(H.TAKHFIF))   -   (MAX(H.M_NAGHD) + MAX(H.MABL_VAR) + MAX(H.MABL_HAV) + ISNULL(MAX(CHK.mabch), 0)) ) <> 0
